import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Gemini 三层运动解耦：相机 / 主体 / 物理","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-motion-layers.md","filePath":"tools/gemini-motion-layers.md","lastUpdated":1787456457000}'),s={name:"tools/gemini-motion-layers.md"};function n(r,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="gemini-三层运动解耦-相机-主体-物理" tabindex="-1">Gemini 三层运动解耦：相机 / 主体 / 物理 <a class="header-anchor" href="#gemini-三层运动解耦-相机-主体-物理" aria-label="Permalink to &quot;Gemini 三层运动解耦：相机 / 主体 / 物理&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经官方文档逐一核实；不同模型对多层运动语义的解析能力不同，请以各自官方文档为准。</li></ul></div><blockquote><p>提问：怎么在一条 prompt 里同时锁住「镜头运动 + 物体原本运动 + 物理规律」三个层次而不互相打架？</p></blockquote><h2 id="核心逻辑" tabindex="-1">核心逻辑 <a class="header-anchor" href="#核心逻辑" aria-label="Permalink to &quot;核心逻辑&quot;">​</a></h2><p>在一条 Prompt 中让「镜头运动」「主体运动」和「物理规律」同时生效且不互相干扰，核心逻辑是：<strong>「语法分层隔离（Syntax Decoupling）+ 明确参考系关联（Frame of Reference）+ 统一时间速率（Time Scale）」</strong>。</p><p>模型在解析单句长文本时，如果把相机动作和物体动作混在同一个分句里（例如 <code>A french fry falls down as camera zooms in and steam rises</code>），注意力机制会模糊「是谁在向哪个方向移动」。必须采用结构化三层递进句式。</p><h2 id="一、三层标准结构公式" tabindex="-1">一、三层标准结构公式 <a class="header-anchor" href="#一、三层标准结构公式" aria-label="Permalink to &quot;一、三层标准结构公式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Layer 1: 相机运动与参考系] → [Layer 2: 主体自主动作矢量] → [Layer 3: 被动物理碰撞与微观动力学]</span></span></code></pre></div><h3 id="layer-1-相机运动层-camera-reference-frame" tabindex="-1">Layer 1：相机运动层（Camera &amp; Reference Frame） <a class="header-anchor" href="#layer-1-相机运动层-camera-reference-frame" aria-label="Permalink to &quot;Layer 1：相机运动层（Camera &amp; Reference Frame）&quot;">​</a></h3><ul><li><strong>职责</strong>：只定义摄影机在空间中的绝对轨迹，以及相机与主体的运动绑定关系。</li><li><strong>核心词</strong>：<code>static overhead shot</code>／<code>smooth dolly-in along z-axis</code>／<code>camera locked tracking with [Subject]</code>（相机与主体锁定跟随）。</li></ul><h3 id="layer-2-主体运动层-subject-kinematics" tabindex="-1">Layer 2：主体运动层（Subject Kinematics） <a class="header-anchor" href="#layer-2-主体运动层-subject-kinematics" aria-label="Permalink to &quot;Layer 2：主体运动层（Subject Kinematics）&quot;">​</a></h3><ul><li><strong>职责</strong>：只定义主体的主动位移、受力方向与起始 / 终点状态。</li><li><strong>核心词</strong>：<code>moving from left to right</code>／<code>colliding at a 45-degree angle</code>／<code>snapping into two halves</code>。</li></ul><h3 id="layer-3-物理规律层-physics-passive-dynamics" tabindex="-1">Layer 3：物理规律层（Physics &amp; Passive Dynamics） <a class="header-anchor" href="#layer-3-物理规律层-physics-passive-dynamics" aria-label="Permalink to &quot;Layer 3：物理规律层（Physics &amp; Passive Dynamics）&quot;">​</a></h3><ul><li><strong>职责</strong>：只定义被动的环境响应（重力、惯性、脆裂散射、流体飞溅、空气阻力）。</li><li><strong>核心词</strong>：<code>realistic downward gravitational acceleration</code>／<code>micro-fragments scattering outward along the vector of impact</code>／<code>rising translucent steam dissipating naturally</code>。</li></ul><h2 id="二、防止三个层次「打架」的-3-条铁律" tabindex="-1">二、防止三个层次「打架」的 3 条铁律 <a class="header-anchor" href="#二、防止三个层次「打架」的-3-条铁律" aria-label="Permalink to &quot;二、防止三个层次「打架」的 3 条铁律&quot;">​</a></h2><p><strong>1. 明确参考系（锁定相机是「静止围观」还是「跟随主体」）</strong>：</p><ul><li>若物体高速下落、相机静止：写明 <code>camera remains static while [Subject] falls through the frame from top to bottom</code>。</li><li>若相机跟着物体一起掉：写明 <code>camera tracks downward in sync with the falling [Subject], keeping [Subject] dead-centered</code>。</li></ul><p><strong>2. 物理因果链必须严格单向编写（Action → Reaction）</strong>：先写主要动作，再用 <code>triggering</code>／<code>resulting in</code> 引出次级物理响应，杜绝多主语并列。</p><p>正确范例：<code>...snapping in the middle, instantly triggering micro-crumbs to burst outward due to fracture force</code>。</p><p><strong>3. 全局时间速率必须绝对统一（Global Time Rate）</strong>：切忌在一条 Prompt 里同时出现 <code>rapid crash</code> 和 <code>slow-motion liquid</code>。在句首统一设定全局时间基准（如 <code>In 1000fps ultra slow-motion:</code>），让相机移动速度、物体撞击速度与粒子沉降速度都在同一时间膨胀尺度下计算。</p><h2 id="三、实战标准-prompt-示范" tabindex="-1">三、实战标准 Prompt 示范 <a class="header-anchor" href="#三、实战标准-prompt-示范" aria-label="Permalink to &quot;三、实战标准 Prompt 示范&quot;">​</a></h2><p>场景：高难度微距——推镜头中两个物体相撞脆裂、碎屑受重力散射、热气向上消散。</p><p>结构化英文 Prompt（可直接输入模型）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Camera] A controlled slow dolly-in shot pushing forward along the z-axis with a shallow depth of field.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Subject Action] Simultaneously, two crispy golden French fries collide horizontally at high speed at the center of the frame, snapping instantly upon impact.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Physics &amp; Dynamics] The fracture creates realistic brittle physics: tiny golden crumbs and fine salt crystals violently burst outward along the kinetic vector before falling under gravity, while thin translucent steam gently curls and rises upward, unaffected by the debris.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>8k macro commercial lighting.</span></span></code></pre></div><p>解析：</p><ul><li><strong>相机</strong>：只管向 Z 轴直线慢推（不抢 X / Y 轴空间）。</li><li><strong>主体</strong>：在 X 轴水平相撞并断裂（动作明确）。</li><li><strong>物理</strong>：碎屑沿撞击动量向外炸开后受重力下落（符合动量与重力），蒸汽轻微向上自然升腾（符合热力学），各层物理矢量完全不冲突。</li></ul><h2 id="层次解耦对照表" tabindex="-1">层次解耦对照表 <a class="header-anchor" href="#层次解耦对照表" aria-label="Permalink to &quot;层次解耦对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>容易犯错的写法（易冲突）</th><th>正确的解耦写法（稳定锁定）</th></tr></thead><tbody><tr><td>机位 vs 物体</td><td><code>Camera goes down and fries fall down</code>（模型分不清谁在掉）</td><td><code>Camera stays static at eye level while fries fall vertically past the lens</code></td></tr><tr><td>主体 vs 物理</td><td><code>Fries break and flying crumbs and steam together</code>（粒子粘连）</td><td><code>Fries snap at center, triggering micro-crumbs to scatter radially outward</code></td></tr><tr><td>时间尺度</td><td><code>Fast zoom in slow motion water splash</code>（画面撕裂）</td><td><code>In ultra slow-motion, smooth linear push-in as water droplets splash naturally</code></td></tr></tbody></table><hr><p>关联：本文是 <a href="/tools/gemini-camera-movement">机位与运镜</a> 与 <a href="/tools/gemini-camera-failsafe">运镜翻车词</a> 的进阶篇——前两篇解决「单层运镜怎么写 / 避坑」，本篇解决「相机、主体、物理三层运动在同一条 Prompt 里如何解耦」。</p>`,30)])])}const g=a(s,[["render",n]]);export{h as __pageData,g as default};
